import sys

def main():
	(n, k) = map(int, sys.stdin.readline().split())
	a = n - k
	if a == 1:
		print(2)
		for i in range(k):
			print(1, i + 2)
	elif a > k + 1:
		l = ((a - 1) // k + 1) * 2
		if (a - 1) % k > 1:
			print(l + 2)
		elif (a - 1) % k == 1:
			print(l + 1)
		else:
			print(l)
		c = 2
		for i in range(k):
			print(1, c)
			for j in range(l // 2 - 1):
				print(c, c + 1)
				c += 1
			if i < (a - 1) % k:
				print(c, c + 1)
				c += 1
			c += 1
	else:
		if a == 2:
			print(3)
		else:
			print(4)
		c = 2
		for i in range(a - 1):
			print(1, c)
			print(c, c + 1)
			c += 2
		for i in range(c, n + 1):
			print(1, i)
main()
